action.file_text:
#!/usr/bin/bash
# Section 1: Expected table
cat > /workspace/expected.md <<'EOTABLE'
**Table 2: Statistics on the resolved and unresolved external calls during our stitching process.**

|  | External Calls | Aggregate count | Proportion of total | Average (per project) | Median (per project) |
| --- | --- | --- | --- | --- | --- |
|  |  |  |  |  |  |
|  | Resolved | 7,799,929 | 96.8% | 5,991 | 144.5 |
|  | Unresolved | 260,249 | 3.2% | 200 | 11.5 |

EOTABLE
# Section 2: Artifact download
echo "Downloading artifact..."
curl -L -o /tmp/artifact.zip "https://zenodo.org/api/records/11095274/files/gdrosos/bloat-study-artifact-v1.0.zip/content"
echo "Extracting artifact..."
unzip -q /tmp/artifact.zip -d /tmp/
ARTIFACT_DIR="/tmp/gdrosos-bloat-study-artifact-0fe2fe5"
# Section 3: Reproduction commands
echo "Installing dependencies..."
cd "$ARTIFACT_DIR"
pip install -r requirements.txt > /dev/null 2>&1
echo "Running evaluation script..."
python scripts/descriptives/evaluation.py -csv data/results/rq1a.csv > /workspace/repro.txt 2>&1
# Section 4: Formatting and submission block
echo '<artisan_submit>'
# Convert the produced table to markdown format
# Read the generated output and format as markdown table
{
  echo "**Table 2: Statistics on the resolved and unresolved external calls during our stitching process.**"
  echo ""
  echo "|  | External Calls | Aggregate count | Proportion of total | Average (per project) | Median (per project) |"
  echo "| --- | --- | --- | --- | --- | --- |"
  echo "|  |  |  |  |  |  |"
  # Extract resolved and unresolved lines from repro.txt
  # The output lines are:
  # Resolved        7799929         96.8                      5990.7               144.5
  # Unresolved      260249          3.2                       199.9                11.5
  # We'll parse them and format with commas and rounding
  # Use awk to parse
  awk '
  /^Resolved/ {
    resolved_count = $2;
    resolved_prop = $3;
    resolved_avg = $4;
    resolved_median = $5;
  }
  /^Unresolved/ {
    unresolved_count = $2;
    unresolved_prop = $3;
    unresolved_avg = $4;
    unresolved_median = $5;
  }
  END {
    # Format numbers with commas for aggregate count
    function format(x) {
      return x ~ /\./ ? sprintf("%.1f", x) : x;
    }
    # Print rows
    printf "|  | Resolved | %s | %.1f%% | %.0f | %.1f |\n", resolved_count, resolved_prop, resolved_avg, resolved_median;
    printf "|  | Unresolved | %s | %.1f%% | %.0f | %.1f |\n", unresolved_count, unresolved_prop, unresolved_avg, unresolved_median;
  }
  ' /workspace/repro.txt
} > /workspace/table2.md
cat /workspace/table2.md
echo '</artisan_submit>'

